# render_c4.awk — minimal offline renderer for the C4-PlantUML subset
# produced by structurizr export-c4plantuml. Emits a C4-styled SVG.
# Supports: title, Person, System, Container, SoftwareSystem, Database, Rel.

BEGIN {
  margin = 50
  topY   = 95
  boxW   = 220
  boxH   = 170
  gap    = 250
  n = 0; m = 0
}

function esc(s) {
  gsub(/&/, "\\&amp;", s)
  gsub(/</, "\\&lt;", s)
  gsub(/>/, "\\&gt;", s)
  gsub(/"/, "\\&quot;", s)
  return s
}

# extract key="value" where key is like $descr
function qval(s, key,   re, t) {
  re = "\\$" key "=\"[^\"]*\""
  if (match(s, re)) {
    t = substr(s, RSTART, RLENGTH)
    sub("\\$" key "=\"", "", t)
    sub("\"$", "", t)
    return t
  }
  return ""
}

function wrap(s, maxc,   nw, words, i, cur, out) {
  nw = split(s, words, " ")
  cur = ""; out = ""
  for (i = 1; i <= nw; i++) {
    if (cur == "") cur = words[i]
    else if (length(cur) + 1 + length(words[i]) <= maxc) cur = cur " " words[i]
    else { out = out cur "\n"; cur = words[i] }
  }
  if (cur != "") out = out cur
  return out
}

{
  line = $0
  if (line ~ /^title /) {
    t = line
    sub(/^title /, "", t)
    gsub(/<[^>]*>/, "", t)
    title = t
  } else if (match(line, /^(Person|System|Container|SoftwareSystem|Database|Queue|Node)\(/)) {
    n++
    etype[n] = substr(line, 1, RSTART - 1)
    rest = substr(line, RSTART + RLENGTH)
    id = rest; sub(/,.*/, "", id); gsub(/[ \t]/, "", id)
    name = ""
    if (match(rest, /"[^"]*"/)) name = substr(rest, RSTART + 1, RLENGTH - 2)
    eid[n] = id
    ename[n] = name
    edescr[n] = qval(rest, "descr")
    etech[n] = qval(rest, "tech")
    if (etech[n] == "") etech[n] = qval(rest, "techn")
  } else if (match(line, /^Rel(_[UDLR])?\(/)) {
    m++
    rest = substr(line, RSTART + RLENGTH)
    a = rest; sub(/,.*/, "", a); gsub(/[ \t]/, "", a)
    sub(/^[^,]*, */, "", rest)
    b = rest; sub(/,.*/, "", b); gsub(/[ \t]/, "", b)
    sub(/^[^,]*, */, "", rest)
    label = ""
    if (match(rest, /"[^"]*"/)) label = substr(rest, RSTART + 1, RLENGTH - 2)
    ra[m] = a; rb[m] = b; rlabel[m] = label
    rtech[m] = qval(rest, "techn")
    if (rtech[m] == "") rtech[m] = qval(rest, "tech")
  }
}

function colorOf(t) {
  if (t == "Person") return "#0E7C7B"
  if (t == "Container") return "#43C6AC"
  if (t == "Database") return "#0E907D"
  return "#1168BD"
}

function drawIcon(i, x, y,   cx, c) {
  cx = x + boxW / 2
  c = colorOf(etype[i])
  if (etype[i] == "Person") {
    printf "    <circle cx=\"%.0f\" cy=\"%.0f\" r=\"15\" fill=\"#ffffff\"/>\n", cx, y + 38
    printf "    <path d=\"M %.0f %.0f L %.0f %.0f Q %.0f %.0f %.0f %.0f Q %.0f %.0f %.0f %.0f L %.0f %.0f Z\" fill=\"#ffffff\"/>\n", \
      cx - 27, y + 80, cx - 27, y + 70, cx - 27, y + 56, cx, y + 56, cx + 27, y + 56, cx + 27, y + 70, cx + 27, y + 80
  } else if (etype[i] == "Container") {
    printf "    <polygon points=\"%.0f,%.0f %.0f,%.0f %.0f,%.0f %.0f,%.0f\" fill=\"#ffffff\"/>\n", cx, y + 24, cx + 24, y + 34, cx, y + 44, cx - 24, y + 34
    printf "    <polygon points=\"%.0f,%.0f %.0f,%.0f %.0f,%.0f %.0f,%.0f\" fill=\"#ffffff\" fill-opacity=\"0.8\"/>\n", cx - 24, y + 34, cx, y + 44, cx, y + 68, cx - 24, y + 58
    printf "    <polygon points=\"%.0f,%.0f %.0f,%.0f %.0f,%.0f %.0f,%.0f\" fill=\"#ffffff\" fill-opacity=\"0.6\"/>\n", cx + 24, y + 34, cx, y + 44, cx, y + 68, cx + 24, y + 58
  } else {
    printf "    <rect x=\"%.0f\" y=\"%.0f\" width=\"52\" height=\"34\" rx=\"3\" fill=\"#ffffff\"/>\n", cx - 26, y + 22
    printf "    <rect x=\"%.0f\" y=\"%.0f\" width=\"44\" height=\"26\" fill=\"%s\"/>\n", cx - 22, y + 26, c
    printf "    <rect x=\"%.0f\" y=\"%.0f\" width=\"8\" height=\"8\" fill=\"#ffffff\"/>\n", cx - 4, y + 56
    printf "    <rect x=\"%.0f\" y=\"%.0f\" width=\"32\" height=\"4\" rx=\"2\" fill=\"#ffffff\"/>\n", cx - 16, y + 64
  }
}

function drawElement(i,   x, y, cx, c, d, nl, lines, k, ly) {
  x = ex[i]; y = ey[i]; cx = x + boxW / 2
  c = colorOf(etype[i])
  printf "  <g>\n"
  printf "    <rect x=\"%.0f\" y=\"%.0f\" width=\"%d\" height=\"%d\" rx=\"10\" fill=\"%s\"/>\n", x, y, boxW, boxH, c
  drawIcon(i, x, y)
  printf "    <text x=\"%.0f\" y=\"%.0f\" font-size=\"15\" font-weight=\"bold\" fill=\"#ffffff\" text-anchor=\"middle\">%s</text>\n", cx, y + 104, esc(ename[i])
  d = edescr[i]
  if (etype[i] == "Container" && etech[i] != "") d = d " (" etech[i) ")"
  nl = split(wrap(d, 30), lines, "\n")
  ly = y + 124
  for (k = 1; k <= nl; k++) {
    printf "    <text x=\"%.0f\" y=\"%.0f\" font-size=\"11\" fill=\"#ffffff\" text-anchor=\"middle\">%s</text>\n", cx, ly, esc(lines[k])
    ly += 15
  }
  printf "  </g>\n"
}

END {
  W = margin * 2 + n * boxW + (n - 1) * gap
  legendTop = topY + boxH + 35
  H = legendTop + 55
  for (i = 1; i <= n; i++) {
    ex[i] = margin + (i - 1) * (boxW + gap)
    ey[i] = topY
  }

  printf "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"%d\" height=\"%d\" viewBox=\"0 0 %d %d\" font-family=\"Helvetica, Arial, sans-serif\">\n", W, H, W, H
  printf "  <rect width=\"%d\" height=\"%d\" fill=\"#ffffff\"/>\n", W, H
  if (title != "")
    printf "  <text x=\"%d\" y=\"40\" font-size=\"20\" font-weight=\"bold\" fill=\"#333333\">%s</text>\n", margin, esc(title)
  if (subtitle != "")
    printf "  <text x=\"%d\" y=\"62\" font-size=\"12\" fill=\"#666666\">%s</text>\n", margin, esc(subtitle)

  for (i = 1; i <= n; i++) drawElement(i)

  for (j = 1; j <= m; j++) {
    ai = 0; bi = 0
    for (i = 1; i <= n; i++) {
      if (eid[i] == ra[j]) ai = i
      if (eid[i] == rb[j]) bi = i
    }
    if (ai == 0 || bi == 0) continue
    if (bi > ai) { x1 = ex[ai] + boxW; x2 = ex[bi] } else { x1 = ex[ai]; x2 = ex[bi] + boxW }
    y1 = ey[ai] + boxH / 2
    y2 = ey[bi] + boxH / 2
    dx = x2 - x1; dy = y2 - y1
    len = sqrt(dx * dx + dy * dy)
    if (len == 0) continue
    ux = dx / len; uy = dy / len
    px = -uy; py = ux
    ex2 = x2 - 10 * ux; ey2 = y2 - 10 * uy
    printf "  <line x1=\"%.0f\" y1=\"%.0f\" x2=\"%.0f\" y2=\"%.0f\" stroke=\"#666666\" stroke-width=\"1.5\"/>\n", x1, y1, ex2, ey2
    printf "  <polygon points=\"%.0f,%.0f %.0f,%.0f %.0f,%.0f\" fill=\"#666666\"/>\n", x2, y2, ex2 + 5 * px, ey2 + 5 * py, ex2 - 5 * px, ey2 - 5 * py
    mx = (x1 + x2) / 2
    my = (y1 + y2) / 2
    if (rlabel[j] != "")
      printf "  <text x=\"%.0f\" y=\"%.0f\" font-size=\"12\" fill=\"#333333\" text-anchor=\"middle\">%s</text>\n", mx, my - 10, esc(rlabel[j])
    if (rtech[j] != "")
      printf "  <text x=\"%.0f\" y=\"%.0f\" font-size=\"11\" fill=\"#666666\" text-anchor=\"middle\">[%s]</text>\n", mx, my + 22, esc(rtech[j])
  }

  # legend
  printf "  <line x1=\"%d\" y1=\"%.0f\" x2=\"%d\" y2=\"%.0f\" stroke=\"#dddddd\" stroke-width=\"1\"/>\n", margin, legendTop, W - margin, legendTop
  lx = margin
  ly = legendTop + 28
  hasPerson = 0; hasSystem = 0; hasContainer = 0
  for (i = 1; i <= n; i++) {
    if (etype[i] == "Person") hasPerson = 1
    else if (etype[i] == "Container") hasContainer = 1
    else hasSystem = 1
  }
  if (hasPerson) {
    printf "  <rect x=\"%d\" y=\"%.0f\" width=\"22\" height=\"22\" rx=\"5\" fill=\"#0E7C7B\"/>\n", lx, ly - 17
    printf "  <text x=\"%d\" y=\"%.0f\" font-size=\"12\" fill=\"#444444\">Person</text>\n", lx + 30, ly - 2
    lx += 120
  }
  if (hasSystem) {
    printf "  <rect x=\"%d\" y=\"%.0f\" width=\"22\" height=\"22\" rx=\"5\" fill=\"#1168BD\"/>\n", lx, ly - 17
    printf "  <text x=\"%d\" y=\"%.0f\" font-size=\"12\" fill=\"#444444\">Software System</text>\n", lx + 30, ly - 2
    lx += 170
  }
  if (hasContainer) {
    printf "  <rect x=\"%d\" y=\"%.0f\" width=\"22\" height=\"22\" rx=\"5\" fill=\"#43C6AC\"/>\n", lx, ly - 17
    printf "  <text x=\"%d\" y=\"%.0f\" font-size=\"12\" fill=\"#444444\">Container</text>\n", lx + 30, ly - 2
    lx += 120
  }
  if (m > 0) {
    printf "  <line x1=\"%d\" y1=\"%.0f\" x2=\"%d\" y2=\"%.0f\" stroke=\"#666666\" stroke-width=\"1.5\"/>\n", lx, ly - 6, lx + 40, ly - 6
    printf "  <polygon points=\"%d,%.0f %.0f,%.0f %.0f,%.0f\" fill=\"#666666\"/>\n", lx + 48, ly - 6, lx + 40, ly - 11, lx + 40, ly - 1
    printf "  <text x=\"%d\" y=\"%.0f\" font-size=\"12\" fill=\"#444444\">Relationship</text>\n", lx + 58, ly - 2
  }
  printf "</svg>\n"
}

